insert into public.portfolio_content(id,document,revision) values ('draft','{"profile":{"name":"Amr Ahmed Abdelhay","location":"Cairo, Egypt · Open to opportunities","title":"Digital Marketing & Brand Growth Specialist","headline":"I build brands","headlineSecond":"from the ground up.","intro":"connecting strategy, content, paid media, design, sales, and digital execution.","portrait":"/amr-ahmed-abdelhay.jpeg","about":"With a 2020 degree in Management Information Systems, I bring a business-first lens to creative work. I moved from sales and Odoo-based operations into end-to-end marketing—then expanded into brand design, short-form video, AI-assisted production, Flutter, and e-commerce development.","github":"https://github.com/AmrAbdelhay"},"services":["Brand Strategy","Content Creation","Paid Media","Creative Design","Social Media","Short-form Video","AI Workflows","Digital Products"],"caseStudies":[{"name":"Noga Home","slug":"noga","monogram":"N","image":"/work/brands/noga-logo.png","market":"Home textiles · Egypt","period":"2025—Present","role":"Founder · End-to-end brand, sales & e-commerce","summary":"Built and ran the brand end to end: identity, product visuals, content, offers, Meta ads, direct customer conversations and sales, order operations, and the e-commerce website.","tags":["Brand building","Meta Ads","Content","E-commerce","Sales"],"accent":"#d9b54a","assetHint":"Identity designed and launched from scratch","metrics":[{"value":"3.2K+","label":"contacts"},{"value":"7.6×","label":"est. ROAS"},{"value":"EGP 112K","label":"revenue"}],"template":"noga"},{"name":"RS","slug":"rs","monogram":"RS","image":"/work/brands/rs-logo.png","market":"Financial services · Egypt","period":"Feb 2024—Present","role":"Sales → Operations → Marketing","summary":"Started in sales, generating approximately EGP 200K in sales over three months. Worked in operations, then moved into digital marketing in July 2024: content, design, photography, video, social media, campaigns, and reporting.","tags":["Sales","Operations","Marketing","Design","Video"],"accent":"#2574d9","assetHint":"Rising Star Financial Services","metrics":[{"value":"~EGP 200K","label":"sales"},{"value":"3 months","label":"sales period"}],"template":"rs"},{"name":"Aleem","slug":"aleem","monogram":"A","image":"/work/brands/aleem-logo.png","market":"Business education · Saudi Arabia","period":"Selected work","role":"Content & Design","summary":"Created Arabic educational content and social designs for business and professional learning, tailored to a Saudi audience.","tags":["Content","Design","Saudi market"],"accent":"#1b777b","assetHint":"Business education for the Saudi market","metrics":[],"template":"aleem"}],"projects":[{"title":"Noga Home Identity","short":"BRAND / 01","image":"/work/brands/noga-logo.png","category":"Brand","description":"From the brand identity to product creative and the customer experience.","tone":"lime","status":"live","link":"/work/noga"},{"title":"Noga Paid Growth","short":"META / 02","image":"","category":"Paid Media","description":"Campaigns, customer conversations, order outcomes, and direct selling.","tone":"blue","status":"live","link":"/work/noga"},{"title":"RS: Sales to Marketing","short":"RS / 03","image":"/work/brands/rs-logo.png","category":"Content","description":"Sales and operations before the move into digital marketing in July 2024.","tone":"orange","status":"live","link":"/work/rs"},{"title":"Aleem Social Designs","short":"ALEEM / 04","image":"/work/aleem/design-02.webp","category":"Content","description":"Arabic educational and promotional designs for a Saudi business-learning audience.","tone":"cyan","status":"live","link":"/work/aleem"},{"title":"Short-form Production","short":"VIDEO / 04","image":"","category":"Video","description":"Original photography and concise social-first edits.","tone":"violet","status":"placeholder","link":""},{"title":"Noga Home Store","short":"WEB / 05","image":"","category":"Development","description":"Custom e-commerce storefront and admin workflow.","tone":"rose","status":"live","link":"https://github.com/AmrAbdelhay/noga-home-store"},{"title":"Flutter Note App","short":"APP / 06","image":"","category":"Development","description":"A focused Flutter note-taking application.","tone":"cyan","status":"live","link":"https://github.com/AmrAbdelhay/NoteApp"},{"title":"Flutter Application","short":"APP / 07","image":"","category":"Development","description":"Selected mobile application project built with Flutter.","tone":"navy","status":"live","link":"https://github.com/AmrAbdelhay/Flutter-App"},{"title":"E-commerce Project","short":"CODE / 08","image":"","category":"Development","description":"A commerce-focused web development project.","tone":"gold","status":"live","link":"https://github.com/AmrAbdelhay/e-commerce"}],"experience":[{"period":"Jul 2024—Present","role":"Digital Marketing & Brand Growth Specialist","company":"RS","description":"Content, design, photography, video, social operations, paid media, and performance reporting."},{"period":"2025—Present","role":"Founder & Brand Growth Lead","company":"Noga Home","description":"Built and operate the brand''s complete marketing, sales, and digital ecosystem."},{"period":"Selected work","role":"Content & Social Media Specialist","company":"Aleem · Saudi Arabia","description":"Content, design, moderation, and publishing for business and financial education."},{"period":"Feb—Jul 2024","role":"Sales & Operations","company":"RS","description":"Approximately EGP 200K in sales across three months, followed by customer operations, Odoo ERP data entry, and reporting."}],"stack":[{"name":"Marketing","items":["Meta Ads Manager","Business Suite","Content Strategy","Moderation","Reporting"]},{"name":"Design & video","items":["Photoshop","Premiere Pro","CapCut","VN","Photography"]},{"name":"AI production","items":["ChatGPT","Gemini","Claude","Runway","Kling","Higgsfield"]},{"name":"Business & tech","items":["Odoo ERP","Excel","PowerPoint","Flutter","GitHub","E-commerce"]}],"aleemDesigns":[{"image":"/work/aleem/design-01.webp","label":"سجّل الآن — دعوة للتسجيل"},{"image":"/work/aleem/design-02.webp","label":"تعلّم كأنك على رأس العمل"},{"image":"/work/aleem/design-03.webp","label":"لو سألوك بكرة: رجعت كام؟"},{"image":"/work/aleem/design-04.webp","label":"منتجك الأكثر مبيعًا"},{"image":"/work/aleem/design-05.webp","label":"تحس إنك جرّبت كل طرق التسويق؟"},{"image":"/work/aleem/design-06.webp","label":"نفس القوائم، قراءة مختلفة"}],"details":{"noga":{"headline":"From first idea to every customer order.","intro":"Noga Home is the full story of a brand I built and operated myself. My work spans what customers see, how they discover the products, the conversations that turn interest into orders, and the website that brings it together.","chapters":[{"number":"01","title":"Brand & product creative","text":"Developed the brand''s visual direction, created product designs and campaign assets, and produced content for the social pages.","evidence":"Brand identity · Product imagery · Social posts"},{"number":"02","title":"Content & paid growth","text":"Planned offers and creative, ran Meta campaigns, tested content, and followed the results from advertising to customer contact.","evidence":"Campaign screenshots · Creative tests · Post performance"},{"number":"03","title":"Sales & customer operations","text":"Spoke directly with customers, answered questions, sold through chat, followed orders, and managed the customer experience beyond the ad click.","evidence":"Sales process · Conversations · Delivered orders"},{"number":"04","title":"E-commerce website","text":"Built the online storefront and the digital shopping experience for Noga Home, alongside the day-to-day brand operations.","evidence":"Store screens · Customer journey · Development work"},{"number":"05","title":"Video & production","text":"Product photography, edits, short videos, and social-first creative belong alongside the campaigns that used them.","evidence":"Product shoots · Reels · Video edits"}]},"rs":{"headline":"Sales first. Then operations. Then marketing.","intro":"My RS work developed across three connected roles. I started close to customers, moved into the systems behind the business, and began working in digital marketing in July 2024.","chapters":[{"number":"01","title":"Sales · from February 2024","text":"Worked with customers and generated approximately EGP 200,000 in sales over a three-month period.","evidence":"~EGP 200K sales · 3 months"},{"number":"02","title":"Operations · before July 2024","text":"Handled operational coordination, Odoo ERP data entry, and reporting. This gave me a closer view of the customer and business workflow.","evidence":"Customer operations · Odoo · Reports"},{"number":"03","title":"Digital marketing · July 2024 onward","text":"Created designs and content, photographed and edited short-form video, managed publishing and moderation, worked on Meta campaigns, and reported performance.","evidence":"Designs · Video · Campaign results · Engaging posts"}]},"aleem":{"headline":"Content and design for business learning.","intro":"For Aleem, I worked on the words and the visuals: Arabic educational and promotional content shaped for a Saudi audience. The designs below are selected examples of that work.","chapters":[{"number":"01","title":"Educational content","text":"Developed content angles and copy around business, professional learning, courses, and practical skills.","evidence":"Content concepts · Arabic copy · Course posts"},{"number":"02","title":"Social design","text":"Turned topics and course messages into clear branded social visuals for Aleem''s audience.","evidence":"Six selected designs below"}]}},"rsWorks":[{"id":"student-testimonial","title":"A student''s perspective","description":"Shady Mohamed shares his experience at the Financial Accountant Workshop.","role":"Filming, editing & post caption writing","badge":"Organic + Paid","views":"742K","likes":"~1K","comments":"215","shares":"39","url":"https://www.facebook.com/reel/1538084490731890","note":"Combined organic and paid counts; breakdown unavailable.","video":"/work/rs/student-testimonial.mp4","poster":"/work/rs/student-testimonial.jpg"},{"id":"cash-flow-workshop","title":"Cash flow, explained","description":"A moment from the financial statements workshop, captured as a short educational reel.","role":"Post caption writing","badge":"Organic","views":"124K","likes":"996","comments":"46","shares":"108","url":"https://www.facebook.com/reel/4395420284070934","note":"Organic performance · No paid promotion.","video":"/work/rs/cash-flow-workshop.mp4","poster":"/work/rs/cash-flow-workshop.jpg"}],"brandPlatforms":{"aleem":[{"platform":"Facebook","url":"https://www.facebook.com/aleemacademy.sa"},{"platform":"Instagram","url":"https://www.instagram.com/aleem_saa/"}],"rs":[{"platform":"Facebook","url":"https://www.facebook.com/rspaac"},{"platform":"Instagram","url":"https://www.instagram.com/rspaac/"}],"noga":[{"platform":"Facebook","url":"https://www.facebook.com/profile.php?id=61579710984123"},{"platform":"Instagram","url":"https://www.instagram.com/noga_home.store/"}]}}'::jsonb,1),('published','{"profile":{"name":"Amr Ahmed Abdelhay","location":"Cairo, Egypt · Open to opportunities","title":"Digital Marketing & Brand Growth Specialist","headline":"I build brands","headlineSecond":"from the ground up.","intro":"connecting strategy, content, paid media, design, sales, and digital execution.","portrait":"/amr-ahmed-abdelhay.jpeg","about":"With a 2020 degree in Management Information Systems, I bring a business-first lens to creative work. I moved from sales and Odoo-based operations into end-to-end marketing—then expanded into brand design, short-form video, AI-assisted production, Flutter, and e-commerce development.","github":"https://github.com/AmrAbdelhay"},"services":["Brand Strategy","Content Creation","Paid Media","Creative Design","Social Media","Shor